package com.personal.assistant.module.knowledge.service;import com.personal.assistant.module.knowledge.dto.KnowledgeRequest;import com.personal.assistant.module.knowledge.entity.KnowledgeEntry;import com.personal.assistant.module.knowledge.mapper.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.jdbc.core.JdbcTemplate;import java.time.LocalDateTime;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class KnowledgeServiceTest{@Mock KnowledgeEntryMapper entries;@Mock KnowledgeLinkMapper links;@Mock JdbcTemplate jdbc;@InjectMocks KnowledgeService service;@Test void manualEntryKeepsOwnerAndReviewSchedule(){ArgumentCaptor<KnowledgeEntry>c=ArgumentCaptor.forClass(KnowledgeEntry.class);service.create(8L,new KnowledgeRequest("Spring 笔记","# 内容","java","assistant","后端",LocalDateTime.of(2026,8,1,9,0),3));verify(entries).insert(c.capture());assertEquals(8L,c.getValue().getUserId());assertEquals("MANUAL",c.getValue().getSourceType());assertEquals(3,c.getValue().getReviewIntervalDays());}}
